        "904": { n: "Availability of an approved WEP", t: "SP 70.13330 cl.3.3" },
        "905": { n: "Substrate cleaning", t: "Substrate cleared of dust, dirt, cement laitance, oils\nInternal company standard (cl.5.1.5 of SP 17.13330.2017 was deleted by Amendment No.4 (2024); cl.5.1.3/5.1.7 do not govern substrate cleaning)" },
        "906": { n: "Substrate moisture", t: "SP 71.13330.2017 Table 5.1 (SP 17.13330.2017 does not regulate substrate moisture): RC slabs ≤5%; cement-sand screed ≤10% (as amended by Amendment No. 2); sand asphalt concrete ≤2.5%; prefabricated screed ≤12%" },
        "907": { n: "Substrate strength", t: "≥ 20 MPa\nInternal company standard (cl.5.2 of GOST 22690-2015 describes the instrument measurement method, not the 20 MPa strength requirement)" },
        "908": { n: "Substrate flatness", t: "along the slope and on a horizontal surface ±5 mm; across the slope and on a vertical surface ±10 mm\nSP 71.13330.2017 Table 5.1" },
        "909": { n: "Installation", t: "Overlap ≥ 100 mm, taping done per the technology\nSP 17.13330.2017 cl 4.4b" },
        "910": { n: "Run-up onto vertical structures", t: "SP17.13330.2017 cl. 4.4c. The vapour barrier must be raised to a height not less than the thickness of the thermal insulation layer" },
        "911": { n: "Sealing", t: "Sealing of all joints, no punctures or folds\nSP 17.13330.2017 cl 4.4c" },
        "912": { n: "Overlap fixing", t: "Overlaps fixed with tape per the manufacturer's TU\nSP 17.13330.2017 cl 4.4b" },
        "913": { n: "Laying", t: "Laid in a staggered/breaking-joint pattern with no cold bridges\nSP 71.13330.2017 cl.5.3.12, 5.3.13" },
        "914": { n: "Gap between boards", t: "≤ 2 mm\nSP 71.13330.2017 Table 5.2" },
        "915": { n: "Board contact across the whole plane", t: "Tight contact of boards across the whole plane\nSP 71.13330.2017 cl. 5.3.10" },
        "916": { n: "Fastening", t: "As per the project and the product data sheet. Internal company standard (cl.5.4.3 of SP 17.13330.2017 governs insulation material properties, not the fastening method)." },
        "917": { n: "Weld-seam width", t: "From 85 to 120 mm. Internal company standard (cl.5.1.24 of SP 17.13330.2017 governs sheet-overlap width, not weld-seam width)" },
        "918": { n: "Run-up onto vertical structures", t: "not less than 300 mm per SP 17.13330.2017 cl. 5.1.20" },
        "919": { n: "Interface zones", t: "Reinforcing interface zones with an additional strip\nSP 17.13330.2017 cl.5.1.18" },
        "920": { n: "Weld quality", t: "Seam 5-15 mm, SP 17.13330.2017 cl. 5.1.16, 5.1.24, SP 71.13330.2017 cl 5.9.1-5.9.7, Table 5.4" },
        "921": { n: "Concrete curing (temperature-humidity regime)", t: "Screeds and monolithic toppings on a cement binder should be kept moist for not less than 7 days after laying, under a moisture-retaining material layer, unless otherwise specified by the material manufacturer. SP 71.13330.2017 8.1.12" },
        "922": { n: "Slope", t: "Non-occupied and inverted roof: not less than 1.5% (SP 17.13330.2017, cl. 5.1.4).\nOccupied roof: 1.5-3.0% (SP 17.13330.2017, table 4.1)." },
        "923": { n: "Cutting into panels/sections", t: "WEP. SP 71.13330.2017 cl.5.1.9: shrinkage joints up to 10 mm wide divide a cement-sand screed into panels not exceeding 6×6 m, and a sand-asphalt-concrete screed into panels not exceeding 4×4 m" },
        "924": { n: "Integrity", t: "Internal company standard (TechnoNICOL roofing installation guide (substrate preparation)). No pitting, no cracks" },
        "925": { n: "Coating type complies with the project", t: "Project" },
        "926": { n: "Finish coating", t: "WEP. No damage; dents, scratches through to metal (for metal roofs), tears (for rolled materials), and chips are not permitted." },
        "927": { n: "Colour and shade", t: "WEP. Minor colour deviations within one material batch are allowed." },
        "928": { n: "Finish-coating tolerances comply with standards", t: "WEP. Depending on the finish/protective layer type" },

