        "1201": { n: "Incoming inspection log for materials used", t: "SP 48.13330.2019 cl. 3.1, Annex B.1" },
        "1202": { n: "Materials are used per the project or as approved", t: "SP48.13330.2019 Annex B, cl. B.1, item 7; Project" },
        "1203": { n: "As-built diagrams for completed works", t: "SP 70.13330 cl.3.5, 3.23" },
        "1204": { n: "Availability of an approved WEP", t: "SP 70.13330 cl.3.3" },
        "1205": { n: "Availability of approved shop drawings (KMD)", t: "SP 70.13330" },
        "1206": { n: "Substrate cleared of dirt, snow, ice, dedusted", t: "Internal company standard (the closest in SP 70.13330.2012 is cl.3.13: no dirt, snow or ice on the erected elements; cleaning of the substrate is not separately regulated)" },
        "1207": { n: "Steel grade of bolts, nuts, washers.", t: "GOST 32484.3-2013, GOST 1759.4-87\nCompliance with the project (usually property class 5.8, 8.8, 10.9)" },
        "1208": { n: "Number of bolts", t: "Compliance with the project (even a single missing bolt is unacceptable)" },
        "1209": { n: "Bolt and hole diameter", t: "SP 16.13330.2017 Table 40 (note 1); SP 70.13330.2012 cl.4.5.1: difference between nominal hole and bolt diameters — up to 3 mm (accuracy class A — no gap)" },
        "1210": { n: "Hole offset", t: "GOST 23118-2019. Tolerance ≤ 2 mm." },
        "1211": { n: "Gap between plates", t: "SP 70.13330.2012 cl.4.5.8: tightness of the assembled pack is checked with a 0.3 mm feeler gauge — it must not penetrate between the parts within the zone bounded by the washer" },
        "1212": { n: "Bolt length", t: "SP 70.13330.2012 cl.4.5.7. Must ensure the bolt end protrudes past the nut by at least 1 full-profile thread (optimally 2-3 threads)" },
        "1213": { n: "Bolt tightening torque", t: "Internal company standard (SP 16.13330.2017 contains no tightening torques; for bolts without controlled tension SP 70.13330.2012 cl.4.5.6 prescribes tightening \"to refusal\" with a force of 294-343 N using a wrench of standardized length): minimum tightening torque 160 N·m, for class 8.8 bolts ≈ 250 N·m (depends on diameter). Torque wrench" },
        "1214": { n: "Tightening uniformity", t: "Internal company standard (cl.4.6.17 of SP 70.13330.2012 limits the excess of the actual torque over the design value to 10% for flange connections, not the difference between adjacent bolts). Difference in tightening torque between adjacent bolts ≤ 10%" },
        "1215": { n: "Absence of corrosion", t: "SP 70.13330.2012 cl.4.5.8 (cleaning of contact surfaces from dirt, burrs, ice). Prohibition of rust on threads and contact surfaces — internal company standard (GOST 9.402-2004 concerns surface preparation for painting)" },
        "1216": { n: "Maximum nut skew", t: "≤ 5° — internal company standard (GOST 32484.3-2013 contains no angular criterion for nut skew)" },
        "1217": { n: "Anchor type and grade", t: "Compliance with the project (chemical anchor, mechanical, embedded, etc.)" },
        "1218": { n: "Anchor diameter", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (setting parameters)). Tolerance: ±0.5 mm" },
        "1219": { n: "Hole cleanliness", t: "Holes clean (GOST R 56731-2023 / SP 513.1325800.2022: the drilled hole must be cleaned of drilling dust/slurry before anchor installation)" },
        "1220": { n: "Installation depth", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (setting parameters)). ±5% from design (but not more than ±3 mm)" },
        "1221": { n: "Distance to the concrete edge", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (edge distances cmin)). ≥ 5d (d — anchor diameter), but not less than 50 mm" },
        "1222": { n: "Distance between anchors", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (anchor spacing smin)). ≥ 10d (for loaded connections)" },
        "1223": { n: "Tightening torque", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (tightening torque Tinst/Tmax)). 15% of the design value (for chemical anchors — per manufacturer's data)" },
        "1224": { n: "No cracks in the concrete", t: "Internal company standard (anchor qualification tests at 0,3 mm crack width (GOST R 58387, ETA)). Crack width in the anchor zone ≤ 0.3 mm" },
        "1225": { n: "Corrosion protection", t: "Internal company standard (GOST ISO 10684-2015 cl.8.3: fastener zinc coating, mean ≥50 µm). For steel anchors — galvanising or painting (thickness ≥ 50 µm)" },
        "1226": { n: "Anchor hole diameter", t: "Internal company standard (Hilti Anchor Fastening Technology Manual (drill bit diameter d0)). Tolerance: +1.0 mm" },
        "1227": { n: "Anchor offset from axis", t: "Internal company standard (established site work practice). Tolerance: ≤ 2 mm" },
        "1228": { n: "Anchor tilt angle", t: "Internal company standard (industry guide on fastener installation control (plumb ≤5°)). Tolerance: ≤ 5°" },
        "1229": { n: "Pull-out load", t: "Internal company standard (STO 44416204-010-2010: field pull-out testing of anchors). Test: ≥ 90% of rated value" },
        "1230": { n: "Guard height", t: "As per the project. Roofs, balconies and loggias — not less than 1200 mm (for buildings taller than 30 m — not less than 1100 mm);\\nStair flights not less than 900 mm (GOST 25772-2021)" },
        "1231": { n: "Tests and loads", t: "Horizontal load on guard handrails not less than 0.3 kN/m\nSP 20.13330.2016 cl.8.2.6 g) (as amended by Amendment No. 2)" },
        "1232": { n: "Edge preparation", t: "Edge bevel angle: (25±2)° per edge (23–27°), total groove angle (50±4)° (for metal thickness > 4 mm) (GOST 5264-80)" },
        "1233": { n: "Gap between edges", t: "1–4 mm (depending on metal thickness; GOST 5264-80, butt joints types C17–C19)" },
        "1234": { n: "Surface cleanliness", t: "Internal company standard (RD 34.15.132-96 cl.5.6: cleaning of edges and weld zone). No rust, oil, or scale (light scale ≤ 0.1 mm is allowed)" },
        "1235": { n: "Grade of welding consumables", t: "Compliance with the project (electrodes, wire, flux)" },
        "1236": { n: "Weld shape, surface and dimensions", t: "Weld leg: deviation up to 30% of the nominal (design) value (GOST 5264-80). Evenly scaled weld, no burn-through, no overlaps, undercuts or interruptions. Smooth transition to the base metal (compliance with KM and KMD drawings)" },
        "1237": { n: "External weld defects", t: "Internal company standard (RD 34.15.132-96: weld quality control for steel structures). No cracks, undercuts, overlaps. Pores ≤ 0.5 mm (isolated)" },
        "1238": { n: "Penetration depth", t: "Internal company standard (established site work practice). ≥ 80% of metal thickness (for critical welds)" },
        "1239": { n: "Non-destructive testing methods", t: "Visual - 100%; UT - not less than 0.5% of weld length (volume increased per project for critical welds); Radiographic - not less than 0.5% of weld length (spot-check) (SP 70.13330.2012 cl.10.4)" },
        "1240": { n: "Surface preparation", t: "Cleanliness grade: Sa 2½ per ISO 8501-1 (for standard coatings) (SP 28.13330.2017 / GOST 9.402)" },
        "1241": { n: "Coating adhesion", t: "≤ 1 point (cross-cut method, for coating thickness up to 250 µm) (SP 28.13330.2017, Amendment No.1)" },
        "1242": { n: "Coating thickness", t: "As per the project, but not less than 120 µm - 200 µm (SP 28.13330.2017: total coating thickness in the range 120–320 µm depending on the environment's aggressiveness class)" },
        "1243": { n: "Absence of defects", t: "Not permitted: paint-coating peeling, presence of rust. No scale on welds (SP 28.13330.2017)" },
        "1244": { n: "Opacity/hiding power", t: "Not less than 2 coats, no show-through" },
        "1245": { n: "Galvanising (if applied)", t: "Layer thickness: 45–85 µm depending on metal thickness (mean value per GOST 9.307-2021 Table 2: from 45 µm for metal up to 1.5 mm, up to 85 µm for metal over 6 mm) (hot-dip galvanising)" },

        "1301": { n: "Incoming inspection log for insulated glass units (IGU)", t: "SP 48.13330.2019 cl. 3.1, Annex B.1. As per the project. Products in accordance with the approved reference sample. Check the IGU glazing formula." },
